using System;
using System.Text;

public class ArcfourPrng {
    private byte[] _state0 = new byte[256];
    private byte[] _state = new byte[256];
    private byte _i, _j;

    public void SetKey\(byte[] keyData\) {
        for \(int i = 0; i < 256; i++\) _state0[i] = \(byte\)i;
        _i = 0; _j = 0;
        int keyIndex = 0;
        for \(int i = 0; i < 256; i++\) {
            _j = \(byte\)\(_j + _state0[i] + keyData[keyIndex]\);
            byte temp = _state0[i];
            _state0[i] = _state0[_j];
            _state0[_j] = temp;
            keyIndex = \(keyIndex + 1\) % keyData.Length;
        }
        Array.Copy\(_state0, _state, 256\);
        _i = 0; _j = 0;
    }

    public void Reset\(\) {
        Array.Copy\(_state0, _state, 256\);
        _i = 0; _j = 0;
    }

    public byte Rand\(\) {
        _i++;
        _j = \(byte\)\(_j + _state[_i]\);
        byte temp = _state[_i];
        _state[_i] = _state[_j];
        _state[_j] = temp;
        return _state[\(_state[_i] + _state[_j]\) & 0xFF];
    }
}

public class Xor256Test {
    private ArcfourPrng _prng = new ArcfourPrng\(\);
    private byte[] _key;
    private int _rounds;
    private byte _ucPrev0, _ucPrev;

    public void Initialize\(string keyData, int rounds\) {
        _rounds = rounds;
        _key = new byte[256];
        byte[] keyBytes = Encoding.UTF8.GetBytes\(keyData\);
        for \(int i = 0, j = 0; i < 256; i++, j = \(j + 1\) % keyBytes.Length\)
            _key[i] = keyBytes[j];
        _prng.SetKey\(_key\);
        _ucPrev0 = _prng.Rand\(\);
        _ucPrev = _ucPrev0;
    }

    public void ResetChain\(\) {
        _prng.Reset\(\);
        _prng.Rand\(\);
        _ucPrev = _ucPrev0;
    }

    public byte[] Encrypt\(byte[] input\) {
        byte[] output = new byte[input.Length];
        for \(int i = 0; i < input.Length; i++\) {
            _ucPrev ^= input[i];
            byte cipher = \(byte\)\(\(_ucPrev ^ _prng.Rand\(\)\) + _prng.Rand\(\)\);
            for \(int j = 1; j < _rounds; j++\) {
                cipher ^= _prng.Rand\(\);
                cipher = \(byte\)\(cipher + _prng.Rand\(\)\);
            }
            output[i] = cipher;
        }
        return output;
    }

    public byte[] Decrypt\(byte[] input\) {
        byte[] seqX = new byte[_rounds];
        byte[] seqM = new byte[_rounds];
        byte[] output = new byte[input.Length];

        for \(int i = 0; i < input.Length; i++\) {
            for \(int j = 0; j < _rounds; j++\) {
                seqX[j] = _prng.Rand\(\);
                seqM[j] = _prng.Rand\(\);
            }
            byte plain = input[i];
            for \(int j = _rounds - 1; j > 0; j--\) {
                if \(seqM[j] <= plain\) plain = \(byte\)\(plain - seqM[j]\);
                else plain = \(byte\)\(\(plain + \(byte\)\(~seqM[j]\)\) + 1\);
                plain ^= seqX[j];
            }
            if \(seqM[0] <= plain\) plain = \(byte\)\(plain - seqM[0]\);
            else plain = \(byte\)\(\(plain + \(byte\)\(~seqM[0]\)\) + 1\);
            plain ^= \(byte\)\(_ucPrev ^ seqX[0]\);
            output[i] = plain;
            _ucPrev ^= plain;
        }
        return output;
    }

    public static string Test\(string plain\) {
        var t = new Xor256Test\(\);
        t.Initialize\(""TGA_util"", 4\);
        t.ResetChain\(\);
        byte[] enc = t.Encrypt\(Encoding.UTF8.GetBytes\(plain\)\);
        string hex = BitConverter.ToString\(enc\).Replace\(""-"", """"\);

        t.Initialize\(""TGA_util"", 4\);
        t.ResetChain\(\);
        byte[] dec = t.Decrypt\(enc\);
        string decStr = Encoding.UTF8.GetString\(dec\);

        return ""원본: "" + plain + ""\\n암호화: "" + hex + ""\\n복호화: "" + decStr + ""\\n일치: "" + \(plain == decStr\);
    }
}
''@

